#include <bits/stdc++.h>
using namespace std;
static int ADDT[343][343],NEG[343];
int enc(int x,int y,int z){return x*49+y*7+z;} array<int,3> decv(int q){return {q/49,(q/7)%7,q%7};} int inv7(int a){for(int x=1;x<7;x++)if(a*x%7==1)return x;return 0;}
using Counts=array<int,343>;
vector<pair<int,int>> makeU(int a){int u=inv7(a);return {{enc(1,0,0),6},{enc(0,1,0),6},{enc(0,0,1),a},{enc((7-u)%7,(7-u)%7,1),7-a}};} Counts fromU(int a){Counts c{};for(auto[g,m]:makeU(a))c[g]=m;return c;}
string keyCounts(const Counts&c){string s;for(int i=0;i<343;i++)if(c[i])s+=to_string(i)+":"+to_string(c[i])+",";return s;}
bool hasShortZero(const Counts&c,int h){vector<int>e;for(int g=0;g<343;g++)if(c[g])e.push_back(g);function<bool(int,int,int)>rec=[&](int i,int len,int sum){if(len>h)return false;if(i==(int)e.size())return len>0&&sum==0;int g=e[i],acc=0;for(int t=0;t<=min(c[g],h-len);t++){if(rec(i+1,len+t,ADDT[sum][acc]))return true;acc=ADDT[acc][g];}return false;};return rec(0,0,0);}
vector<vector<int>> zeroVectors(const Counts&c,int lo,int hi,vector<int>*oe=nullptr){vector<int>e;for(int g=0;g<343;g++)if(c[g])e.push_back(g);if(oe)*oe=e;vector<vector<int>>out;vector<int>cur(e.size());function<void(int,int,int)>rec=[&](int i,int len,int sum){if(len>hi)return;if(i==(int)e.size()){if(len>=lo&&sum==0)out.push_back(cur);return;}int g=e[i],acc=0;for(int t=0;t<=c[g];t++){cur[i]=t;rec(i+1,len+t,ADDT[sum][acc]);acc=ADDT[acc][g];}cur[i]=0;};rec(0,0,0);return out;}
bool exactlyZ2(const Counts&P){vector<int>e;auto z=zeroVectors(P,9,9,&e);vector<int>cap;for(int g:e)cap.push_back(P[g]);for(int i=0;i<(int)z.size();i++)for(int j=i;j<(int)z.size();j++){bool ok=true;for(int k=0;k<(int)cap.size();k++)if(z[i][k]+z[j][k]>cap[k]){ok=false;break;}if(ok)return false;}return true;}
struct PR{int a;string type;Counts P;};
vector<PR> genPairs(){vector<PR>out;set<string>seen;for(int a=1;a<=3;a++){Counts U=fromU(a);set<int>us;for(int g=0;g<343;g++)if(U[g])us.insert(g);int light=enc(0,0,1),u=inv7(a),heavy=enc((7-u)%7,(7-u)%7,1);vector<int>news;for(int g=1;g<343;g++)if(!us.count(g))news.push_back(g);auto tryV=[&](Counts V,string ty){int sum=0,len=0;for(int g=0;g<343;g++)if(V[g]){len+=V[g];int acc=0;for(int q=0;q<V[g];q++)acc=ADDT[acc][g];sum=ADDT[sum][acc];}if(len!=9||sum)return;Counts P=U;for(int g=0;g<343;g++)P[g]+=V[g];if(hasShortZero(P,8))return;if(!exactlyZ2(P))return;string k=to_string(a)+"|"+keyCounts(V);if(seen.insert(k).second)out.push_back({a,ty,P});};for(int i=0;i<(int)news.size();i++)for(int j=i+1;j<(int)news.size();j++){int x=news[i],y=news[j];for(int side=0;side<2;side++){int s=side?heavy:light;if(U[s]>=6)continue;for(int c=1;c<=6-U[s];c++)for(int r=1;r<=6;r++){int t=9-c-r;if(t<1||t>6)continue;Counts V{};V[s]=c;V[x]=r;V[y]=t;tryV(V,side?"s3H":"s3L");}}if(U[light]<6&&U[heavy]<6)for(int c=1;c<=6-U[light];c++)for(int d=1;d<=6-U[heavy];d++)for(int r=1;r<=6;r++){int t=9-c-d-r;if(t<1||t>6)continue;Counts V{};V[light]=c;V[heavy]=d;V[x]=r;V[y]=t;tryV(V,"s4");}}}return out;}
vector<int> minDepth(const Counts&c,int h){const int INF=99;vector<int>dp(343,INF);dp[0]=0;for(int g=0;g<343;g++)if(c[g]){auto old=dp;for(int s=0;s<343;s++)if(old[s]<=h){int acc=0;for(int t=1;t<=c[g]&&old[s]+t<=h;t++){acc=ADDT[acc][g];int ns=ADDT[s][acc];dp[ns]=min(dp[ns],old[s]+t);}}}return dp;}
bool appendValid(const vector<int>&chosen,int x,int h,const vector<int>&md){int d=chosen.size(),lim=1<<d;for(int mask=0;mask<lim;mask++){int sz=1+__builtin_popcount((unsigned)mask);if(sz>h)continue;int s=x;for(int i=0;i<d;i++)if(mask>>i&1)s=ADDT[s][chosen[i]];if(md[NEG[s]]<=h-sz)return false;}return true;}
void enumerateIndependent(const Counts&base,int m,int h,function<void(const vector<int>&)>cb){auto md=minDepth(base,h);vector<int>allowed;for(int x=0;x<343;x++)if(base[x]<6&&md[NEG[x]]>h-1)allowed.push_back(x);array<int,343>mult{};vector<int>chosen;function<void(int,int,int)>dfs=[&](int start,int depth,int total){if(depth==m-1){int x=NEG[total];auto it=lower_bound(allowed.begin(),allowed.end(),x);if(it==allowed.end()||*it!=x)return;if(!chosen.empty()&&x<chosen.back())return;if(mult[x]>=6-base[x])return;if(!appendValid(chosen,x,h,md))return;auto seq=chosen;seq.push_back(x);cb(seq);return;}for(int pos=start;pos<(int)allowed.size();pos++){int x=allowed[pos];if(mult[x]>=6-base[x])continue;if(!appendValid(chosen,x,h,md))continue;mult[x]++;chosen.push_back(x);dfs(pos,depth+1,ADDT[total][x]);chosen.pop_back();mult[x]--;}};dfs(0,0,0);}
uint64_t code(const vector<int>&v){uint64_t z=0,m=1;for(int x:v){z+=m*x;m*=7;}return z;}
bool hasPack4PairComplement(const Counts&c){vector<int>e;auto z=zeroVectors(c,8,13,&e);vector<int>cap;for(int g:e)cap.push_back(c[g]);unordered_set<uint64_t>codes;vector<vector<int>>unions;for(int i=0;i<(int)z.size();i++)for(int j=i;j<(int)z.size();j++){vector<int>u(cap.size());bool ok=true;for(int k=0;k<(int)cap.size();k++){u[k]=z[i][k]+z[j][k];if(u[k]>cap[k]){ok=false;break;}}if(ok){auto q=code(u);if(codes.insert(q).second)unions.push_back(move(u));}}for(auto&u:unions){vector<int>v(cap.size());for(int k=0;k<(int)cap.size();k++)v[k]=cap[k]-u[k];if(codes.count(code(v)))return true;}return false;}
int main(){for(int i=0;i<343;i++){auto a=decv(i);NEG[i]=enc((7-a[0])%7,(7-a[1])%7,(7-a[2])%7);for(int j=0;j<343;j++){auto b=decv(j);ADDT[i][j]=enc((a[0]+b[0])%7,(a[1]+b[1])%7,(a[2]+b[2])%7);}}auto pairs=genPairs();map<int,map<string,int>>pc,cc;for(auto&r:pairs)pc[r.a][r.type]++;assert(pairs.size()==26);assert(pc[1]["s3L"]==12);assert(pc[2]["s3L"]==4&&pc[2]["s4"]==6);assert(pc[3]["s3L"]==2&&pc[3]["s3H"]==2);long long comps=0,pack=0;set<string>dist;for(auto&r:pairs){enumerateIndependent(r.P,9,7,[&](const vector<int>&w){Counts B=r.P;for(int x:w)B[x]++;comps++;cc[r.a][r.type]++;dist.insert(keyCounts(B));if(hasPack4PairComplement(B))pack++;});}assert(comps==1634&&pack==1634&&dist.size()==1634);assert(cc[1]["s3L"]==876);assert(cc[2]["s3L"]==198&&cc[2]["s4"]==142);assert(cc[3]["s3L"]==212&&cc[3]["s3H"]==206);cout<<"{\"status\":\"SUPPORT6_9919_CLOSURE_INDEPENDENT_GREEN\",\"pair_candidates\":26,\"completions\":"<<comps<<",\"distinct_sequences\":"<<dist.size()<<",\"four_pack\":"<<pack<<"}\n";}
